    body: "<!doctype html>\n<html lang=\"en\" class=\"dark\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <title>GoodHarness</title>\n    <!--\n      Stock shadcn is light-first and switches on a `.dark` class, but GoodHarness is dark today and\n      flipping it to light would be a surprise unrelated to the restyle. So `.dark` is the default,\n      set here rather than at mount so there is no light flash before React runs, and the one thing\n      that turns it off is an explicit `prefers-color-scheme: light`. No switcher, nothing stored.\n\n      `color-scheme` follows the same rule declaratively, so the transcript scrollbar and any native\n      control are painted to match rather than staying light on a dark page.\n    -->\n    <meta name=\"color-scheme\" content=\"dark light\" />\n    <script>\n      if (window.matchMedia(\"(prefers-color-scheme: light)\").matches) {\n        document.documentElement.classList.remove(\"dark\");\n        document.documentElement.style.colorScheme = \"light\";\n      }\n    </script>\n    <script type=\"module\" crossorigin src=\"/assets/index-RpFR0EHN.js\"></script>\n    <link rel=\"stylesheet\" crossorigin href=\"/assets/index-D12xEA0r.css\">\n  </head>\n  <body><div id=\"root\"></div></body>\n</html>\n",
